const item = $input.item;
const json = item.json || {};

function getHeader(headers, name) {
  const h = (headers || []).find(h => h.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : '';
}

function base64UrlDecode(data) {
  if (!data) return '';
  const base64 = data.replace(/-/g, '+').replace(/_/g, '/');
  const buff = Buffer.from(base64, 'base64');
  return buff.toString('utf-8');
}

function extractBodies(payload) {
  let html = '';
  let text = '';
  if (!payload) return { html, text };

  function walk(part) {
    if (!part) return;
    const mimeType = part.mimeType || '';
    if (part.body && part.body.data) {
      const decoded = base64UrlDecode(part.body.data);
      if (mimeType === 'text/html') html += decoded;
      else if (mimeType === 'text/plain') text += decoded;
    }
    if (part.parts && part.parts.length) {
      for (const p of part.parts) walk(p);
    }
  }

  walk(payload);
  return { html, text };
}

function extractAttachmentNames(payload) {
  const names = [];
  function walk(part) {
    if (!part) return;
    if (part.filename && part.filename.length > 0) {
      names.push(part.filename);
    }
    if (part.parts && part.parts.length) {
      for (const p of part.parts) walk(p);
    }
  }
  walk(payload);
  return names;
}

// The message ID always comes from the original trigger item, even if this
// particular fetch failed, so the "Open Gmail" link always works.
const triggerJson = $('Gmail Trigger').item.json;
const messageId = json.id || triggerJson.id;
const threadId = json.threadId || triggerJson.threadId;

const fetchFailed = !!json.error || !json.payload;

const headers = json.payload ? json.payload.headers : [];
const from = getHeader(headers, 'From');
const subject = getHeader(headers, 'Subject') || (fetchFailed ? '(could not fetch email)' : '(no subject)');
const dateHeader = getHeader(headers, 'Date');
// The real email Message-ID header (e.g. "<abc123@mail.gmail.com>"), used to
// deep-link directly to this message via Gmail's rfc822msgid: search.
const rfc822MessageId = getHeader(headers, 'Message-ID') || getHeader(headers, 'Message-Id');

const { html, text } = extractBodies(json.payload);
const bodyHtml = html;
const bodyText = text || (bodyHtml ? bodyHtml.replace(/<[^>]+>/g, ' ') : '');
const attachmentNames = extractAttachmentNames(json.payload);

let receivedDate;
if (json.internalDate) {
  receivedDate = new Date(Number(json.internalDate)).toISOString();
} else if (dateHeader) {
  const parsed = new Date(dateHeader);
  receivedDate = isNaN(parsed.getTime()) ? new Date().toISOString() : parsed.toISOString();
} else {
  receivedDate = new Date().toISOString();
}

return {
  json: {
    messageId: messageId,
    threadId: threadId,
    rfc822MessageId: rfc822MessageId,
    sender: from,
    subject: subject,
    receivedDate: receivedDate,
    bodyHtml: bodyHtml,
    bodyText: bodyText.trim(),
    attachmentNames: attachmentNames,
    fetchFailed: fetchFailed
  }
};

const item = $input.item;
const html = item.json.bodyHtml || '';
const text = item.json.bodyText || '';

function decodeHtmlEntities(str) {
  return String(str)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

const links = new Set();

// 1) Explicit hyperlinks the sender put in the email: <a href="...">
const hrefRegex = /<a\s+[^>]*href\s*=\s*["']([^"']+)["'][^>]*>/gi;
let match;
while ((match = hrefRegex.exec(html)) !== null) {
  links.add(decodeHtmlEntities(match[1]));
}

// 2) Plain URLs written directly in the visible/readable text of the email.
//    Scan the plain-text body (or HTML with tags stripped), never the raw
//    HTML markup -- otherwise css/background-image/script/tracking-pixel
//    URLs baked into the markup get picked up as if they were links.
const plainTextSource = text || html.replace(/<[^>]+>/g, ' ');
const urlRegex = /https?:\/\/[^\s"'<>\)\]]+/gi;
let urlMatch;
while ((urlMatch = urlRegex.exec(plainTextSource)) !== null) {
  links.add(decodeHtmlEntities(urlMatch[0].replace(/[.,;:!?]+$/, '')));
}

// 3) Drop anything that isn't genuine sender content: unsubscribe/tracking
//    links, asset files, social-share/icon links, and platform navigation
//    chrome (e.g. LinkedIn's header/badge/feed links that appear in every
//    notification email, carrying tokens like lipi=, midToken=, trk=eml-).
const noisePatterns = [
  /unsubscribe/i,
  /email-settings/i,
  /\bopt-?out\b/i,
  /\/track(ing)?\//i,
  /\bclick\.[^/]+\//i,
  /\bmailtrack\b/i,
  /list-manage\.com/i,
  /sendgrid\.net\/wf\//i,
  /hubspotlinks\.com/i,
  /mailerlite\.com\/track/i,
  /googleusercontent\.com/i,
  /gstatic\.com/i,
  /fonts\.googleapis\.com/i,
  /w3\.org/i,
  /schema\.org/i,
  /facebook\.com\/(sharer|share)/i,
  /twitter\.com\/(intent|share)/i,
  /linkedin\.com\/(shareArticle|share)/i,
  /wa\.me\//i,
  /\.(png|jpe?g|gif|svg|webp|ico|css|js|woff2?|ttf)(\?|$)/i,
  // platform email-template navigation/tracking chrome, not sender content
  /[?&]lipi=/i,
  /[?&]midToken=/i,
  /[?&]midSig=/i,
  /[?&]otpToken=/i,
  /[?&]trkEmail=/i,
  /[?&]trk=eml-/i,
  /linkedin\.com\/comm\//i,
  /linkedin\.com\/e\/v2\//i,
  /linkedin\.com\/psettings\//i,
  /linkedin\.com\/notifications\//i
];

const contentLinks = [...links].filter(link => {
  // Very long, heavily-tokenized URLs are almost always auto-generated
  // tracking/navigation links rather than something a person typed or pasted.
  const isExcessivelyLong = link.length > 180;
  const isNoise = noisePatterns.some(pattern => pattern.test(link));
  return !isNoise && !isExcessivelyLong;
});

const uniqueLinks = [...new Set(contentLinks)];

return {
  json: {
    ...item.json,
    links: uniqueLinks,
    linksJoined: uniqueLinks.join('\n')
  }
};

const item = $input.item;
const json = item.json;
const attachmentNames = json.attachmentNames || [];

const body = (json.bodyText || '').slice(0, 6000);
const links = json.links || [];

const systemPrompt = `You are an assistant that reads emails and produces a concise, factual summary. Only use information present in the email. Respond with ONLY a valid JSON object, no markdown, no code fences, matching exactly this shape:
{"summary": "string", "priority": "Low|Medium|High", "action_items": ["string"], "deadline": "string or null"}
Rules:
- summary: 1-3 sentences, concise, explains what the email is about, mentions important requests, deadlines, and required actions.
- priority: your best estimate of urgency based on content.
- action_items: short list of concrete actions the recipient should take, empty array if none.
- deadline: a date or timeframe mentioned in the email, or null if none.
- Never invent information not present in the email.`;

const userPrompt = `Sender: ${json.sender}
Subject: ${json.subject}
Attachments: ${attachmentNames.length ? attachmentNames.join(', ') : 'None'}
Links found: ${links.length ? links.join(', ') : 'None'}

Email body:
${body || '(empty body)'}`;

return {
  json: {
    ...json,
    aiSystemPrompt: systemPrompt,
    aiUserPrompt: userPrompt
  }
};

const aiItem = $input.item;
const sourceItem = $('Build AI Prompt').item;
const source = sourceItem.json;

let summary = '';
let priority = 'Low';
let actionItems = [];
let deadline = null;

const aiError = aiItem.json && aiItem.json.error;

if (!aiError) {
  try {
    const candidates = aiItem.json && aiItem.json.candidates;
    const content = (candidates && candidates[0] && candidates[0].content && candidates[0].content.parts && candidates[0].content.parts[0])
      ? candidates[0].content.parts[0].text
      : '';
    const cleaned = String(content).replace(/```json/gi, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    summary = parsed.summary || '';
    priority = parsed.priority || 'Low';
    actionItems = Array.isArray(parsed.action_items) ? parsed.action_items : [];
    deadline = parsed.deadline || null;
  } catch (e) {
    summary = 'AI summary unavailable (could not parse model response).';
  }
} else {
  const errMsg = (aiError && (aiError.message || JSON.stringify(aiError))) || 'unknown error';
  summary = `AI summary unavailable (request failed: ${errMsg})`;
}

if (!summary) {
  summary = 'No summary generated.';
}

return {
  json: {
    messageId: source.messageId,
    threadId: source.threadId,
    rfc822MessageId: source.rfc822MessageId,
    sender: source.sender,
    subject: source.subject,
    receivedDate: source.receivedDate,
    links: source.links || [],
    linksJoined: source.linksJoined || '',
    attachmentNames: source.attachmentNames || [],
    summary: summary,
    priority: priority,
    actionItems: actionItems,
    deadline: deadline
  }
};

const json = $json;

const dateObj = json.receivedDate ? new Date(json.receivedDate) : new Date();
const dateFormatted = dateObj.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

let gmailUrl;
if (json.rfc822MessageId) {
  // Gmail reads the URL fragment (#search/...) directly as literal text --
  // it is never sent to a server and never URL-decoded by Gmail's client JS.
  // encodeURIComponent() would turn ":" and "@" into %3A/%40, which breaks
  // Gmail's rfc822msgid: operator recognition, so we deliberately leave the
  // Message-ID unencoded here.
  const cleanId = String(json.rfc822MessageId).replace(/^</, '').replace(/>$/, '').trim();
  gmailUrl = `https://mail.google.com/mail/u/0/#search/rfc822msgid:${cleanId}`;
} else {
  gmailUrl = `https://mail.google.com/mail/u/0/#all/${json.threadId || json.messageId}`;
}
const openGmailFormula = `=HYPERLINK("${gmailUrl}","\ud83d\udce7 Open Gmail")`;

const attachmentNames = json.attachmentNames || [];
const attachmentsColumn = attachmentNames.length
  ? `Yes: ${attachmentNames.join(', ')}`
  : 'None';

function wrapEveryNWords(text, n) {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines = [];
  for (let i = 0; i < words.length; i += n) {
    lines.push(words.slice(i, i + n).join(' '));
  }
  return lines.join('\n');
}

const wrappedSummary = wrapEveryNWords(json.summary, 8);
const wrappedSubject = wrapEveryNWords(json.subject, 8);

return {
  json: {
    date: dateFormatted,
    sender: json.sender || '',
    subject: wrappedSubject,
    summary: wrappedSummary,
    links: json.linksJoined || (json.links ? json.links.join('\n') : ''),
    attachments: attachmentsColumn,
    openGmail: openGmailFormula,
    messageId: json.messageId || '',
    processedAt: new Date().toISOString()
  }
};
